SU_WEIDONG_JPEG = """"""

def looks_like_image(data: bytes) -> bool:
    if len(data) < 1500:
        return False
    return (
        data.startswith(b"\xff\xd8\xff")
        or data.startswith(b"\x89PNG\r\n\x1a\n")
        or data.startswith(b"GIF87a")
        or data.startswith(b"GIF89a")
        or (data[:4] == b"RIFF" and data[8:12] == b"WEBP")
    )

def fetch(url: str) -> bytes:
    parsed_host = urllib.parse.urlparse(url).netloc
    referer = "https://www.bimsa.cn/" if "bimsa" in parsed_host else (
        "https://www.bucea.edu.cn/" if "bucea" in parsed_host else "https://www.google.com/"
    )
    request = urllib.request.Request(
        url,
        headers={
            "User-Agent": "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 Chrome/126 Safari/537.36",
            "Accept": "image/avif,image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8",
            "Referer": referer,
        },
    )
    with urllib.request.urlopen(request, timeout=30) as response:
        return response.read()

def vendor(name: str, sources: list[str]) -> None:
    target = OUT / name
    errors = []
    for url in sources:
        try:
            data = fetch(url)
            if not looks_like_image(data):
                raise ValueError(f"response is not an image ({len(data)} bytes)")
            target.write_bytes(data)
            print(f"[ok] {name} <- {url} ({len(data)} bytes)")
            return
        except Exception as exc:
            errors.append(f"{url} :: {exc}")
            print(f"[retry] {name}: {exc}")
            time.sleep(1)
    if target.exists() and looks_like_image(target.read_bytes()):
        print(f"[keep] {name}: download failed, retaining existing vendored file")
        return
    raise RuntimeError(f"Unable to vendor {name}\n" + "\n".join(errors))

def main() -> None:
    for name, sources in PEOPLE.items():
        vendor(name, sources)

    su_target = OUT / "su-weidong.jpg"
    su_target.write_bytes(base64.b64decode(SU_WEIDONG_JPEG))
    print(f"[ok] su-weidong.jpg <- embedded user-provided portrait ({su_target.stat().st_size} bytes)")

if __name__ == "__main__":
    main()
